solutionCode:
enum class Alliance {
    RED,
    BLUE
}

fun describeAlliance(alliance: Alliance): String {
    return when (alliance) {
        Alliance.RED -> "Red Alliance: Go score some points!"
        Alliance.BLUE -> "Blue Alliance: Let's win this match!"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testRedAlliance() {
        Assert.assertEquals("Red Alliance: Go score some points!", describeAlliance(Alliance.RED))
    }

    @Test
    fun testBlueAlliance() {
        Assert.assertEquals("Blue Alliance: Let's win this match!", describeAlliance(Alliance.BLUE))
    }

    @Test
    fun testEnumValues() {
        val values = Alliance.values()
        Assert.assertEquals(2, values.size)
    }
}
